"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The New Babel Uprising', 'author': 'Signature original', 'genre': 'Resistance Networks', 'chapters': [{'n': 1, 'title': 'Contraband', 'text': "In the safehouse, the runner Pax cracked it open — carefully, lovingly, the way you defuse a bomb. What spilled out wasn't data. It was memory. Real memory. Of New Babel before.\n\nThey moved through New Babel like smoke: checkpoints avoided, cameras looped, the concrete humming its electric lullaby. a data chip pulsed in Dane Kim's pocket like a second heart.\n\nthe runner Pax took one look and went pale. 'This is pre-Collapse,' the runner Pax whispered. 'the Algorithm killed people for less than this. We have to move. Now.'"}, {'n': 2, 'title': 'The Network', 'text': "You don't broadcast in New Babel; you whisper, and the whispers multiply. Dane Kim and the runner Pax built the network node by node: a medic here, a runner there, an ex-enforcer with a grudge and a gun.\n\n'They're going to come for us,' the runner Pax said. Dane Kim nodded. 'Let them. We're already everywhere.'\n\nThe Overseer's broadcast that night was the usual: safety, order, gratitude. Dane Kim watched it on a cracked screen and saw, for the first time, the fear underneath. the Algorithm was scared of a data chip. Of memory. Of truth."}, {'n': 3, 'title': 'Blackout', 'text': "At the top, the runner Pax's hands flew. 'Thirty seconds to signal,' the runner Pax said. Below, the Patrol's lights converged like angry stars. Dane Kim stood at the window with a data chip and thought of green things growing.\n\nThe tower's guards were human, which meant they could be convinced. Dane Kim showed them a data chip — thirty seconds of the before — and watched their faces change. They stood aside. Some revolutions are just remembering, together.\n\n'Now,' said the runner Pax. And New Babel — all of New Babel, every screen, every speaker — remembered."}, {'n': 4, 'title': 'The Remembering', 'text': "the Algorithm responded the only way the Algorithm knew: force. The Patrol marched. The drones rose. And the people of New Babel — who had just remembered green, and laughter, and sky — stood in the streets and would not move.\n\nBy dawn the Patrol had stood down — human, after all, and shown the same thirty seconds. the Algorithm was gone by noon, the Algorithm's servers dark. New Babel belonged to its people again. It had only ever been on loan.\n\nDane Kim and the runner Pax were in the tower when the door blew. The ex-enforcer held the stairs long enough. Long enough for what? For the footage to loop. For the memory to root. For the Algorithm's lie to die on every screen at once."}, {'n': 5, 'title': 'After the Static', 'text': "There were trials. the Algorithm's people faced justice — real justice, not the Algorithm's kind, with evidence and mercy both. Some were guilty. Some were just afraid. Dane Kim learned the difference matters.\n\nAnd when the new council asked Dane Kim to lead, Dane Kim laughed and went back to the food lines. Leaders, Dane Kim had learned, are just people who show up. Dane Kim shows up.\n\nDane Kim kept the dead chip in a pocket. A reminder: that truth is a seed, that seeds die to grow, that one a data chip in the right hands at the right time is worth an army."}, {'n': 6, 'title': 'The Habit of Freedom', 'text': "the runner Pax runs the network now — the real one, the open one, the one that belongs to everyone. The code is quieter. The neon is warmer. It turns out freedom has a sound, and it's laughter.\n\nfreedom is a habit — Dane Kim thinks it every time, like a prayer, like a promise. Memory is resistance. Freedom is a habit. Practice daily.\n\nYears later, New Babel has gardens on the roofs and children who've never seen a drone. They learn the story of a data chip in school, and Dane Kim always winces at the statue. 'I just carried it,' Dane Kim protests. Nobody believes that anymore."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

